import type { Data } from '@dnd-kit/abstract'
import type { DroppableInput } from '@dnd-kit/dom'
import type { MaybeRef, MaybeRefOrGetter, ShallowRef } from 'vue'
import type { ElementRef } from '@/types'
import { Droppable } from '@dnd-kit/dom'
import { createContext } from 'reka-ui'
import { computed, toValue, unref, watch } from 'vue'
import { useDeepSignal } from '@/composables/useDeepSignal'
import { useInstance } from '@/composables/useInstance'
import { getElement } from '@/utils'

export const [useDroppableContext, provideDroppableContext] = createContext<{
  droppable: ShallowRef<Droppable>
  elementRef: (elRef: ElementRef) => void
}>('Droppable')

export interface UseDroppableInput<T extends Data = Data>
  extends Omit<DroppableInput<T>, 'element'> {
  element?: MaybeRef<Element | undefined>
}

export function useDroppable<T extends Data = Data>(
  input: MaybeRefOrGetter<UseDroppableInput<T>>,
) {
  const droppable = useInstance(
    (manager) => {
      const _input = toValue(input)
      return new Droppable(
        {
          ..._input,
          register: false,
          element: unref(_input.element),
        },
        manager,
      )
    },
  )
  const trackedDroppable = useDeepSignal(droppable.value)

  const _input = computed(() => toValue(input))
  watch(() => _input.value.id, (id) => {
    droppable.value.id = id
  })
  watch(() => unref(_input.value.element), (element) => {
    droppable.value.element = element
  })
  watch(() => [_input.value.accept, _input.value.collisionDetector, _input.value.type], () => {
    droppable.value.id = _input.value.id
  })
  watch(() => _input.value.data, (data) => {
    data && (droppable.value.data = data)
  })
  watch(() => _input.value.disabled, (disabled) => {
    droppable.value.disabled = disabled === true
  })

  const elementRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (
      !element
      && droppable.value.element?.isConnected
      && !droppable.value.manager?.dragOperation.status.idle
    ) {
      return element
    }

    if (element instanceof Element)
      droppable.value.element = element ?? undefined
  }

  provideDroppableContext({
    droppable,
    elementRef,
  })

  return {
    droppable: trackedDroppable,
    isDropTarget: computed(() => trackedDroppable.value.isDropTarget),

    elementRef,
  }
}
