import type { Data } from '@dnd-kit/abstract'
import type { DraggableInput } from '@dnd-kit/dom'
import type { MaybeRef, MaybeRefOrGetter, ShallowRef } from 'vue'
import type { ElementRef } from '@/types'
import { Draggable } from '@dnd-kit/dom'
import { createContext } from 'reka-ui'
import { computed, toValue, unref, watch } from 'vue'
import { useInstance } from '@/composables/useInstance'
import { getElement } from '@/utils'
import { useDeepSignal } from './useDeepSignal'

export const [useDraggableContext, provideDraggableContext] = createContext<{
  draggable: ShallowRef<Draggable>
  handleRef: (elRef: ElementRef) => void
  elementRef: (elRef: ElementRef) => void
}>('Draggable')

export interface UseDraggableInput<T extends Data = Data>
  extends Omit<DraggableInput<T>, 'handle' | 'element'> {
  handle?: MaybeRef<Element | undefined>
  element?: MaybeRef<Element | undefined>
}

export function useDraggable<T extends Data = Data>(
  input: MaybeRefOrGetter<UseDraggableInput<T>>,
) {
  // const { element, handle } = input
  const draggable = useInstance((manager) => {
    const _input = toValue(input)
    return new Draggable(
      {
        ..._input,
        register: false,
        handle: unref(_input.handle),
        element: unref(_input.element),
      },
      manager,
    )
  })
  const trackedDraggable = useDeepSignal(draggable.value)

  const _input = computed(() => toValue(input))
  watch(() => _input.value.id, (id) => {
    draggable.value.id = id
  })
  watch(() => unref(_input.value.handle), (handle) => {
    draggable.value.handle = handle
  })
  watch(() => unref(_input.value.element), (element) => {
    draggable.value.element = element
  })
  watch(() => _input.value.data, (data) => {
    data && (draggable.value.data = data)
  })
  watch(() => _input.value.disabled, (disabled) => {
    draggable.value.disabled = disabled === true
  })
  watch(() => _input.value.sensors, (sensors) => {
    draggable.value.sensors = sensors
  })
  watch(() => _input.value.modifiers, (modifiers) => {
    draggable.value.modifiers = modifiers
  })
  watch(() => _input.value.feedback, (feedback) => {
    draggable.value.feedback = feedback ?? 'default'
  })
  watch(() => _input.value.alignment, (alignment) => {
    draggable.value.alignment = alignment
  })

  const handleRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (element instanceof Element)
      draggable.value.handle = element ?? undefined

    return undefined
  }
  const elementRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (
      !element
      && draggable.value.element?.isConnected
      && !draggable.value.manager?.dragOperation.status.idle
    ) {
      return element
    }

    if (element instanceof Element)
      draggable.value.element = element ?? undefined
  }

  provideDraggableContext({
    draggable,
    handleRef,
    elementRef,
  })

  return {
    draggable: trackedDraggable,
    isDragging: computed(() => trackedDraggable.value.isDragging),
    isDropping: computed(() => trackedDraggable.value.isDropping),
    isDragSource: computed(() => trackedDraggable.value.isDragSource),

  }
}
