import type { Signal } from '@dnd-kit/state'
import type { ShallowRef } from 'vue'
import { shallowRef } from 'vue'

export function useSignal<T = any>(signal: Signal<T>) {
  const previous = shallowRef(signal.peek()) as ShallowRef<T>

  signal.subscribe((val) => {
    previous.value = val
  })

  return previous
}
