import type { Data } from '@dnd-kit/abstract'
import type { SortableInput } from '@dnd-kit/dom/sortable'
import type { MaybeRef, MaybeRefOrGetter, ShallowRef } from 'vue'
import type { ElementRef } from '@/types'
import { defaultSortableTransition, Sortable } from '@dnd-kit/dom/sortable'
import { batch } from '@dnd-kit/state'
import { createContext } from 'reka-ui'
import { computed, toValue, unref, watch, watchEffect } from 'vue'
import { useDeepSignal } from '@/composables/useDeepSignal'
import { useInstance } from '@/composables/useInstance'
import { getElement } from '@/utils'

export const [useSortableContext, provideSortableContext] = createContext<{
  sortable: ShallowRef<Sortable>
  handleRef: (elRef: ElementRef) => void
  elementRef: (elRef: ElementRef) => void
  sourceRef: (elRef: ElementRef) => void
  targetRef: (elRef: ElementRef) => void
}>('Sortable')

export interface UseSortableInput<T extends Data = Data>
  extends Omit<SortableInput<T>, 'handle' | 'element' | 'target'> {
  handle?: MaybeRef<Element>
  element?: MaybeRef<Element>
  target?: MaybeRef<Element>
}

export function useSortable<T extends Data = Data>(input: MaybeRefOrGetter<UseSortableInput<T>>) {
  const sortable = useInstance((manager) => {
    const _input = toValue(input)
    const transition = { ...defaultSortableTransition, ..._input.transition }

    return new Sortable({
      ..._input,
      transition,
      register: false,
      handle: unref(_input.handle),
      element: unref(_input.element),
      target: unref(_input.target),
    }, manager)
  })
  const trackedSortable = useDeepSignal(sortable.value)

  const _input = computed(() => toValue(input))
  watch(() => _input.value.id, (id) => {
    sortable.value.id = id
  })

  watchEffect(() => {
    batch(() => {
      sortable.value.group = _input.value.group
      sortable.value.index = _input.value.index
    })
  })

  watch(() => _input.value.type, (type) => {
    sortable.value.type = type
  })
  watch(() => _input.value.accept, (accept) => {
    sortable.value.accept = accept
  })
  watch(() => _input.value.data, (data) => {
    data && (sortable.value.data = data)
  })
  watch(() => _input.value.index, () => {
    if (sortable.value.manager?.dragOperation.status.idle && _input.value.transition?.idle) {
      sortable.value.refreshShape()
    }
  })
  watch(() => unref(_input.value.handle), (handle) => {
    sortable.value.handle = handle
  })
  watch(() => unref(_input.value.element), (element) => {
    sortable.value.element = element
  })
  watch(() => unref(_input.value.target), (target) => {
    sortable.value.target = target
  })
  watch(() => _input.value.disabled, (disabled) => {
    sortable.value.disabled = disabled === true
  })
  watch(() => _input.value.sensors, (sensors) => {
    sortable.value.sensors = sensors
  })
  watch(() => _input.value.collisionDetector, (collisionDetector) => {
    sortable.value.collisionDetector = collisionDetector
  })
  watch(() => _input.value.collisionPriority, (collisionPriority) => {
    sortable.value.collisionPriority = collisionPriority
  })
  watch(() => _input.value.feedback, (feedback) => {
    sortable.value.feedback = feedback ?? 'default'
  })
  watch(() => _input.value.transition, (transition) => {
    sortable.value.transition = transition ?? null
  })
  watch(() => _input.value.modifiers, (modifiers) => {
    sortable.value.modifiers = modifiers
  })
  watch(() => _input.value.alignment, (alignment) => {
    sortable.value.alignment = alignment
  })

  const handleRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (element instanceof Element)
      sortable.value.handle = element ?? undefined
  }

  const elementRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (
      !element
      && sortable.value.element?.isConnected
      && !sortable.value.manager?.dragOperation.status.idle
    ) {
      return element
    }

    if (element instanceof Element)
      sortable.value.element = element ?? undefined
  }

  const sourceRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (
      !element
      && sortable.value.source?.isConnected
      && !sortable.value.manager?.dragOperation.status.idle
    ) {
      return element
    }

    if (element instanceof Element)
      sortable.value.source = element ?? undefined
  }

  const targetRef = (elRef: ElementRef) => {
    const element = getElement(elRef)
    if (
      !element
      && sortable.value.target?.isConnected
      && !sortable.value.manager?.dragOperation.status.idle
    ) {
      return element
    }

    if (element instanceof Element)
      sortable.value.target = element ?? undefined
  }

  provideSortableContext({
    sortable,
    handleRef,
    elementRef,
    sourceRef,
    targetRef,
  })

  return {
    sortable: trackedSortable,
    isDragging: computed(() => trackedSortable.value.isDragging),
    isDropping: computed(() => trackedSortable.value.isDropping),
    isDragSource: computed(() => trackedSortable.value.isDragSource),
    isDropTarget: computed(() => trackedSortable.value.isDropTarget),

    handleRef,
    elementRef,
    sourceRef,
    targetRef,

  }
}
