<script lang="ts">
import type { DragDropEvents, Modifiers, Plugins, Renderer, Sensors } from '@dnd-kit/abstract'
import type { Draggable, Droppable } from '@dnd-kit/dom'
import { defaultPreset, DragDropManager } from '@dnd-kit/dom'
import { provideContext } from '@/composables/useDragDropManager'

type Events = DragDropEvents<Draggable, Droppable, DragDropManager>

interface Props {
  manager?: DragDropManager
  plugins?: Plugins
  sensors?: Sensors
  modifiers?: Modifiers
}

interface Emits {
  beforeDragStart: Parameters<Events['beforedragstart']>
  collision: Parameters<Events['collision']>
  dragStart: Parameters<Events['dragstart']>
  dragMove: any // Parameters<Events['dragmove']> // TS2742 error
  dragOver: Parameters<Events['dragover']>
  dragEnd: Parameters<Events['dragend']>
}
</script>

<script setup lang="ts">
import type { Ref } from 'vue'
import { shallowRef, watch, watchEffect } from 'vue'
import { useRenderer } from '@/composables/useRenderer'

const props = defineProps<Props>()
const emits = defineEmits<Emits>()

const manager = shallowRef<DragDropManager | undefined>() as Ref<DragDropManager | undefined>

const { renderer, trackRendering } = useRenderer()

// Create manager only once unless explicitly provided
watchEffect((onCleanup) => {
  // Only recreate if props.manager changes or if we don't have a manager yet
  if (props.manager) {
    // Use provided manager
    if (manager.value !== props.manager) {
      manager.value?.destroy()
      manager.value = props.manager
    }
  }
  else if (!manager.value) {
    // Create new manager only if we don't have one
    manager.value = new DragDropManager(props)
  }

  const _manager = manager.value
  if (!_manager)
    return

  // Set the renderer
  _manager.renderer = renderer

  // Event listeners with proper cleanup tracking
  const removeBeforeDragStart = _manager.monitor.addEventListener('beforedragstart', (event, manager) => {
    trackRendering(() => {
      emits('beforeDragStart', event, manager)
    })
  })

  const removeDragStart = _manager.monitor.addEventListener('dragstart', (event, manager) => {
    emits('dragStart', event, manager)
  })

  const removeDragOver = _manager.monitor.addEventListener('dragover', (event, manager) => {
    trackRendering(() => {
      emits('dragOver', event, manager)
    })
  })

  const removeDragMove = _manager.monitor.addEventListener('dragmove', (event, manager) => {
    trackRendering(() => {
      emits('dragMove', event, manager)
    })
  })

  const removeDragEnd = _manager.monitor.addEventListener('dragend', (event, manager) => {
    trackRendering(() => {
      emits('dragEnd', event, manager)
    })
  })

  const removeCollision = _manager.monitor.addEventListener('collision', (event, manager) => {
    emits('collision', event, manager)
  })

  onCleanup(() => {
    // Remove all event listeners
    if (typeof removeBeforeDragStart === 'function')
      removeBeforeDragStart()
    if (typeof removeDragStart === 'function')
      removeDragStart()
    if (typeof removeDragOver === 'function')
      removeDragOver()
    if (typeof removeDragMove === 'function')
      removeDragMove()
    if (typeof removeDragEnd === 'function')
      removeDragEnd()
    if (typeof removeCollision === 'function')
      removeCollision()

    // Only destroy if we created the manager (not provided via props)
    if (!props.manager && manager.value) {
      manager.value.destroy()
      manager.value = undefined
    }
  })
})

// Watch for changes in manager configuration
watch(() => props.plugins, (plugins) => {
  if (manager.value) {
    manager.value.plugins = plugins ?? defaultPreset.plugins
  }
}, { deep: true, immediate: true })

watch(() => props.sensors, (sensors) => {
  if (manager.value) {
    manager.value.sensors = sensors ?? defaultPreset.sensors
  }
}, { deep: true, immediate: true })

watch(() => props.modifiers, (modifiers) => {
  if (manager.value) {
    manager.value.modifiers = modifiers ?? defaultPreset.modifiers
  }
}, { deep: true, immediate: true })
provideContext({
  manager,
})
</script>

<template>
  <slot />
</template>
