import type { DragDropManager } from '@dnd-kit/dom'
import type { CleanupFunction } from '@dnd-kit/state'
import type { ShallowRef } from 'vue'
import { onMounted, onUnmounted, shallowRef } from 'vue'
import { useDragDropManager } from './useDragDropManager'

export interface Instance<
  T extends DragDropManager<any, any> = DragDropManager<any, any>,
> {
  manager: T | undefined
  register: () => CleanupFunction | void
}

export function useInstance<T extends Instance>(
  initializer: (manager: DragDropManager<any, any> | undefined) => T,
): ShallowRef<T> {
  const { manager } = useDragDropManager()
  const instance = shallowRef(initializer(manager.value)) as ShallowRef<T>
  let cleanup: CleanupFunction | void

  onMounted(() => {
    // Wait for manager to be available
    if (!manager.value) {
      console.warn('DragDropManager not available when registering instance')
      return
    }

    if (instance.value.manager !== manager.value) {
      instance.value.manager = manager.value
    }

    cleanup = instance.value.register()
  })

  onUnmounted(() => {
    if (cleanup && typeof cleanup === 'function') {
      cleanup()
    }
  })

  return instance
}
