import type { ShallowRef } from 'vue'
import { effect, untracked } from '@dnd-kit/state'
import { onMounted, ref, shallowRef, triggerRef } from 'vue'

/** Trigger a re-render when reading signal properties of an object. */
export function useDeepSignal<T extends object | null | undefined>(
  target: T,
): ShallowRef<T> {
  const tracked = ref(new Map<string | symbol, any>())
  const shallowTarget = shallowRef((target
    ? new Proxy(target, {
      get(target, key) {
        const value = (target as any)[key]
        tracked.value.set(key, value)
        return value
      },
    })
    : target)) as ShallowRef<T>

  onMounted(() => {
    if (!target) {
      tracked.value.clear()
      return
    }

    effect(() => {
      for (const entry of tracked.value) {
        const [key] = entry
        const value = untracked(() => entry[1])
        const latestValue = (target as any)[key]

        triggerRef(shallowTarget)
        if (value !== latestValue) {
          tracked.value.set(key, latestValue)
        }
      }
    })
  })

  return shallowTarget
}
