<script setup lang="ts">
import type { PrimitiveProps } from 'reka-ui'
import { Feedback } from '@dnd-kit/dom'
import { computed as signalComputed } from '@dnd-kit/state'
import { unrefElement } from '@vueuse/core'
import { Primitive } from 'reka-ui'
import { computed, ref, watchEffect } from 'vue'
import { useDeepSignal } from '@/composables/useDeepSignal'
import { provideContext, useDragDropManager } from '@/composables/useDragDropManager'
import { useSignal } from '@/composables/useSignal'

const props = defineProps<PrimitiveProps>()
const { manager } = useDragDropManager()

const primitiveRef = ref<InstanceType<typeof Primitive> | null>(null)
const trackableManager = useDeepSignal(manager.value)

const source = useSignal(signalComputed(() => manager.value?.dragOperation.source))

watchEffect((onCleanup) => {
  const el = unrefElement(primitiveRef)
  if (!el)
    return

  const feedback = trackableManager.value?.plugins.find(plugin => plugin instanceof Feedback)
  if (!feedback)
    return

  feedback.overlay = el
  onCleanup(() => {
    feedback.overlay = undefined
  })
})

function noop() {
  return () => {}
}

const patchedManager = computed(() => {
  if (!manager.value)
    return

  const patchedRegistry = new Proxy(manager.value.registry, {
    get(target, property) {
      if (property === 'register' || property === 'unregister') {
        return noop
      }

      return target[property as keyof typeof target]
    },
  })

  return new Proxy(manager.value, {
    get(target, property) {
      if (property === 'registry') {
        return patchedRegistry
      }

      return target[property as keyof typeof target]
    },
  })
})

provideContext({
  manager: patchedManager,
})
</script>

<template>
  <Primitive
    ref="primitiveRef"
    v-bind="props"
    :data-dnd-overlay="true"
  >
    <slot v-if="source" :source />
  </Primitive>
</template>
