import type { Renderer } from '@dnd-kit/abstract'
import { batch } from '@dnd-kit/state'
import { nextTick, ref, watch } from 'vue'

// Ported from: https://github.com/clauderic/dnd-kit/blob/experimental/packages/react/src/core/context/renderer.ts
export function useRenderer() {
  const transitionCount = ref(0)
  const rendering = ref<Promise<void> | null>(null)
  const resolver = ref<(() => void) | null>(null)

  const renderer: Renderer = {
    get rendering() {
      return rendering.value ?? Promise.resolve()
    },
  }

  // Resolve rendering promise when transitionCount changes
  watch(transitionCount, () => {
    resolver.value?.()
    rendering.value = null
    resolver.value = null
  }, { flush: 'post' })

  return {
    renderer,
    trackRendering(callback: () => void) {
      // Create a new rendering promise if one doesn't exist
      if (!rendering.value) {
        rendering.value = new Promise<void>((resolve) => {
          resolver.value = resolve
        })
      }

      nextTick(() => {
        callback()
        transitionCount.value++
      })
    },
  }
}
